mapper.select:
select a.*, distinct_ids.STATUS userStatus, distinct_ids.create_time userCreateTime, distinct_ids.nickname userNickname, a.nickname supplyName from ( select distinct a.id, d.status, d.create_time , d.nickname from system_users a
left join system_org_user b on a.id = b.user_id
left join system_user_role c on a.id = c.user_id
left join system_user_dept e on a.id = e.user_id
left join system_business_user d on a.id = d.user_id
a.deleted = 0 and d.deleted = 0
and d.business_id = #{record.businessId}
and d.business_id = #{businessId}
and (a.username like concat('%', #{record.text}, '%') or a.nickname like concat('%', #{record.text}, '%') or a.mobile like concat('%', #{record.text}, '%') )
and d.status = #{record.status}
and c.role_id in
#{roleId}
and c.deleted = 0
and b.org_id in
#{orgId}
and b.deleted = 0
and e.dept_id in
#{deptId}
and e.deleted = 0
) as distinct_ids join system_users a on a.id = distinct_ids.id ORDER BY distinct_ids.create_time DESC

SELECT u.id, bu.nickname AS nickname, u.nickname AS username, u.mobile AS userMobile, IFNULL(GROUP_CONCAT(o.name SEPARATOR ','), '') AS orgNames FROM system_business_user bu INNER JOIN system_users u ON u.id = bu.user_id AND u.deleted = b'0' LEFT JOIN system_org_user ou ON ou.user_id = u.id AND ou.deleted = b'0' AND ou.business_id = bu.business_id LEFT JOIN system_org o ON ou.org_id = o.id AND o.deleted = b'0' AND o.status = 1 WHERE u.deleted = b'0'
AND bu.business_id = #{businessId}
AND (u.username LIKE CONCAT('%', #{userName}, '%') OR bu.nickname LIKE CONCAT('%', #{userName}, '%') OR u.mobile LIKE CONCAT('%', #{userName}, '%')OR u.nickname LIKE CONCAT('%', #{userName}, '%') )
AND bu.status = 0 GROUP BY u.id, bu.nickname, u.username, u.mobile ORDER BY u.create_time DESC;
